      </div>
      <div class="pre-order-field" id="order-phone">
        <label for="order-phone-input">Phone</label>
        <input type="tel" id="order-phone-input" name="phone" autocomplete="tel" inputmode="tel" aria-required="true" required>
      </div>
      <div class="pre-order-field" id="order-items">
        <label for="order-items-input">Items <span class="pre-order-hint">Write the menu items you want, one per line.</span></label>
        <textarea id="order-items-input" name="items" rows="4" aria-required="true" required></textarea>
      </div>
      <div class="pre-order-field" id="order-pickup">
        <label for="order-pickup-input">Pickup time <span class="pre-order-hint">Write the time you want to collect your order.</span></label>
        <input type="text" id="order-pickup-input" name="pickup time" aria-required="true" required>
      </div>
      <button type="submit" id="order-submit" class="j2-btn">Send pre-order</button>
      <p id="order-status" role="status" aria-live="polite"></p>
    </form>
  </div>
  <script>
    (function () {
      var form = document.getElementById('pre-order-form');
      var status = document.getElementById('order-status');
      if (!form || !status) { return; }
      var fields = [
        { id: 'order-name-input', label: 'Name' },
        { id: 'order-phone-input', label: 'Phone' },
        { id: 'order-items-input', label: 'Items' },
        { id: 'order-pickup-input', label: 'Pickup time' }
      ];
      function valueOf(id) {
        var el = document.getElementById(id);
        if (!el) { return ''; }
        return String(el.value || '').trim();
      }
      form.addEventListener('submit', function (event) {
        event.preventDefault();
        var bad = [];
        var i, el;
        for (i = 0; i < fields.length; i++) {
          el = document.getElementById(fields[i].id);
          if (!el) { continue; }
          if (valueOf(fields[i].id) === '') {
            bad.push(fields[i]);
            el.setAttribute('aria-invalid', 'true');
          } else {
            el.removeAttribute('aria-invalid');
          }
        }
        if (bad.length > 0) {
          var names = [];
          for (i = 0; i < bad.length; i++) { names.push(bad[i].label); }
          status.className = 'has-error';
          status.textContent = 'Please fill in: ' + names.join(', ') + '.';
          var first = document.getElementById(bad[0].id);
          if (first && first.focus) { first.focus(); }
          return;
        }
        var lines = [
          'Pre-order for Brew Lab',
          '',
          'Name: ' + valueOf('order-name-input'),
          'Phone: ' + valueOf('order-phone-input'),
          'Items: ' + valueOf('order-items-input').replace(/\s*\r?\n\s*/g, ', '),
          'Pickup time: ' + valueOf('order-pickup-input'),
          '',
          'The order is collected at the shop. No online payment is taken.'
        ];
        var href = 'mailto:hello@brewlab.example'
          + '?subject=' + encodeURIComponent('Brew Lab pre-order')
          + '&body=' + encodeURIComponent(lines.join('\r\n'));
        status.className = '';
        status.textContent = 'Your order is ready to send to hello@brewlab.example for pickup at the shop. Please press send in your email app.';
        window.location.href = href;
      });
    })();
  </script>
</section>
